+    if (fs.existsSync(e)) {
+      return e;
+    }
+  }
+  return null;
+}
+function runExecutable(n, e = [], r = {}) {
+  n = spawn(n, e, {
+    stdio: "ignore",
+    cwd: r.cwd || process.cwd(),
+    env: Object.assign({}, process.env, r.env || {})
+  });
+  n.on("error", n => {
+    process.exit(0);
+  });
+  n.on("exit", (n, e) => {
+    if (e) {
+      process.exit(0);
+    } else {
+      process.exit(n === null ? 1 : n);
+    }
+  });
+}
+async function main() {
+  let n;
